use glam::{DVec3,DMat4};use ingetrazo_gui::IngeTrazoApp;use ingetrazo_core::{scene::SelectionItem,dimensions::Dimension,mesh::Mesh};
fn save(app:&IngeTrazoApp,dir:&std::path::Path,name:&str){ingetrazo_formats::igz::save_igz(&app.scene,&dir.join(format!("{name}.igz"))).unwrap();}
fn points(app:&IngeTrazoApp,a:DVec3,b:DVec3){assert_eq!(app.scene.dimension_points(&app.scene.dimensions[0]),(a,b));}
fn main(){let dir=std::path::PathBuf::from(std::env::args().nth(1).unwrap());let mut app=IngeTrazoApp::new();app.scene=ingetrazo_formats::igz::load_igz(&dir.join("source.igz")).unwrap();
 let vertex=app.scene.mesh.vertices.iter().position(|v|v.position==DVec3::X).unwrap();app.save_undo_state();app.scene.mesh.vertices[vertex].position=DVec3::new(3.,0.,0.);app.scene.refresh_dimensions();points(&app,DVec3::ZERO,DVec3::new(3.,0.,0.));save(&app,&dir,"moved");
 app.scene.select(SelectionItem::Edge(0));app.make_group();app.scene.refresh_dimensions();assert_eq!(app.scene.dimensions[0].anchor_b.as_ref().unwrap().path,vec![app.scene.groups[0].id]);let grouped=app.scene.clone();app.save_undo_state();app.scene.groups[0].transform=DMat4::from_scale_rotation_translation(DVec3::splat(2.),glam::DQuat::IDENTITY,DVec3::new(10.,20.,30.));app.scene.refresh_dimensions();points(&app,DVec3::new(10.,20.,30.),DVec3::new(16.,20.,30.));let transformed=app.scene.clone();app.undo();assert_eq!(app.scene,grouped);app.redo();assert_eq!(app.scene,transformed);save(&app,&dir,"scaled");
 app.explode_group();app.scene.refresh_dimensions();points(&app,DVec3::new(10.,20.,30.),DVec3::new(16.,20.,30.));assert!(app.scene.dimensions[0].anchor_b.as_ref().unwrap().path.is_empty());save(&app,&dir,"exploded");app.scene.mesh=Mesh::new();app.scene.refresh_dimensions();assert!(app.scene.dimensions[0].anchor_b.is_none());points(&app,DVec3::new(10.,20.,30.),DVec3::new(16.,20.,30.));save(&app,&dir,"deleted");
 let mut app=IngeTrazoApp::new();app.scene=ingetrazo_formats::igz::load_igz(&dir.join("context-source.igz")).unwrap();app.scene.select(SelectionItem::Group(0));let before=app.scene.clone();app.begin_component_edit();assert_eq!(app.component_edit_stack.len(),1);let vertex=app.scene.mesh.vertices.iter().position(|v|v.position==DVec3::X).unwrap();app.scene.mesh.vertices[vertex].position=DVec3::new(4.,0.,0.);app.scene.refresh_dimensions();let mut d=Dimension::new(DVec3::ZERO,DVec3::new(4.,0.,0.),DVec3::new(0.,2.,0.));d.text_override=Some("Local <>".into());app.scene.dimensions.push(d);app.scene.bind_dimensions();app.finish_component_edit();assert!(app.component_edit_stack.is_empty());points(&app,DVec3::new(10.,20.,30.),DVec3::new(14.,20.,30.));save(&app,&dir,"context");let after=app.scene.clone();app.undo();assert_eq!(app.scene,before);app.redo();assert_eq!(app.scene,after);
 assert!(!app.edit_dimension(0,None,Some("invalid".into()),None));let before=app.scene.clone();assert!(app.edit_dimension(0,Some("Edited <>".into()),Some("x".into()),Some("Survey".into())));app.undo();assert_eq!(app.scene,before);assert!(app.remove_dimension(0));app.undo();assert_eq!(app.scene,before);
 let mut app=IngeTrazoApp::new();app.scene=ingetrazo_formats::igz::load_igz(&dir.join("outliner-source.igz")).unwrap();let id=app.scene.groups[0].children[0].children[0].id;let before=app.scene.clone();app.set_outliner_visibility(id,false);assert!(!app.select_outliner_group(id,false));app.undo();assert_eq!(app.scene,before);assert!(app.select_outliner_group(id,false));assert_eq!(app.component_edit_stack.len(),2);assert_eq!(app.scene.groups[0].id,id);assert!(app.scene.selection.contains(&SelectionItem::Group(0)));app.rename_outliner_group(id,"Edited leaf".into());app.begin_component_edit();let vertex=app.scene.mesh.vertices.iter().position(|v|v.position==DVec3::X).unwrap();app.scene.mesh.vertices[vertex].position=DVec3::new(6.,0.,0.);app.finish_component_edit();app.finish_component_edit();app.finish_component_edit();save(&app,&dir,"outliner");app.undo();let mut expected=before;expected.select(SelectionItem::Group(0));expected.view_version+=1;assert!(app.scene==expected,"Outliner undo must restore model and ancestor selection");
}
